import subprocess, json
from pandoc import pandoc_syntax_spec as spec
opts,_=spec[0]
def run(args, stdin="hi\n"):
    p=subprocess.run(["pandoc"]+args+["-t","plain"],input=stdin,capture_output=True,text=True,timeout=30)
    return p.returncode, (p.stderr+p.stdout)
problems=[]
for n in opts:
    for s in [n.flag]+n.alias:
        long = s.startswith("--")
        if n.kind=="Flag":
            if long:
                rc,out=run([s+"=x"])
                if "doesn't allow an argument" not in out and "does not take an argument" not in out: problems.append((s,"flag accepted =x",out[:80]))
        else:
            rc,out=run([s])   # missing value -> error
            if "requires an argument" not in out: problems.append((s,"no error w/o value",out[:80]))
            if long and not n.eq:
                # separate-word form must be accepted (no 'requires an argument')
                rc,out=run([s,"1"])
                if "requires an argument" in out or "unrecognized" in out: problems.append((s,"separate value rejected",out[:80]))
            if n.eq and long:
                rc,out=run([s+"=x"])
                if "doesn't allow" in out: problems.append((s,"=x rejected",out[:80]))
        if n.kind=="Selection":
            rc,out=run([s+"=bogus"] if long else [s,"bogus"])
            if rc==0: problems.append((s,"bogus choice accepted"))
            for c in n.choices:
                rc,out=run([s+"="+c]) 
                if rc!=0 and "bogus" in out: problems.append((s,c,out[:80]))
        if n.kind=="Integer" and long:
            rc,out=run([s+"=abc"])
            if rc==0: problems.append((s,"non-integer accepted"))
            rc,out=run([s+"=2"])
            if rc!=0 and "argument" in out.lower(): problems.append((s,"integer 2 rejected",out[:120]))
print("problems:", *problems, sep="\n")
